import{_ as d,a0 as r,w as s,s as i,ao as p,I as o,x as t,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Red Hat正與Intel緊密協作，力爭在Fedora 21中默認加入Wayland | LCTT x X-CMD","titleTemplate":false,"description":"Red Hat正與Intel緊密協作，力爭在Fedora 21中默認加入Wayland | LCTT (201309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Red Hat正與Intel緊密協作，力爭在Fedora 21中默認加入Wayland | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Red Hat正與Intel緊密協作，力爭在Fedora 21中默認加入Wayland | LCTT (201309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201309/Red Hat and Intel Working Closely to Bring Wayland as Default for Fedora 21","title":"Red Hat正與Intel緊密協作，力爭在Fedora 21中默認加入Wayland","tag":"201309","desc":""},"relativePath":"201309/Red Hat and Intel Working Closely to Bring Wayland as Default for Fedora 21.md","filePath":"[post].md"}'),f={name:"201309/Red Hat and Intel Working Closely to Bring Wayland as Default for Fedora 21.md"};function u(y,a,C,W,m,I){const e=r("Link");return s(),i("div",null,[a[11]||(a[11]=p('<h1 id="red-hat正與intel緊密協作-力爭在fedora-21中默認加入wayland" tabindex="-1">Red Hat正與Intel緊密協作，力爭在Fedora 21中默認加入Wayland <a class="header-anchor" href="#red-hat正與intel緊密協作-力爭在fedora-21中默認加入wayland" aria-label="Permalink to “Red Hat正與Intel緊密協作，力爭在Fedora 21中默認加入Wayland”">​</a></h1><p><strong>為了使Wayland支持GNOME，Red Hat與Intel的開發者緊密合作，希望能為Wayland加入Fedora21做好及時準備。</strong></p><p>Ubuntu曾企圖征服FOSS（Free and Open Source Software自由和開源軟件）世界的秘密計劃被Intel的一紙聲明挫敗，至少到現在為止，Ubuntu仍未能翻身。但如今，Intel開發者的真正計劃也被揭露了。</p><p>拋開那些戲劇化的劇情，實際上Intel為Wayland的未來投入巨資已不是秘密，Intel的開發者們正加緊與Red Hat的合作，爭取將GNOME Shell變為一個&quot;碼農&quot;（譯註，意指GNOME Shell只完成表層的外圍工作）。</p><p>來自Red Hat的Christian Schaller在他的個人Blog中寫道：“我們在Red Hat的團隊一直在和我們的同行Intel緊密協作，合併並穩固相關的補丁包，保證Wayland能夠支持GNOME，同時查看堆棧中還有哪些地方需要進一步改進。”</p><p>看起來這個小組當前的目標是為Fedora 20準備一個足夠的技術預覽版本，至少目前是這樣。這不是一個正式項目，但至少應該會給人們一個值得期待的idea。</p><p>Ubuntu13.10預定於10月份發佈，在這個特殊的時間點上，Canonical是否會急切的使出全力推出Mir，目前還並不明朗。</p><p>Schaller在他的Blog中還寫道，“因此，一旦確信用户不會感到負面影響，我們才會最終用Wayland替代X服務器。所以，在Fedora 21中默認採用Wayland還是X服務器，這仍然是一個懸而未決的問題。”</p><p>這場顯示服務端之間的“戰爭”即將決出一個贏家，那就是終端用户。為了提供更好的用户體驗，決戰雙方，Intel和Canonical都更加充滿鬥志。無論誰勝誰負，最終受益的都將是我們這些用户。</p>',9)),o("p",null,[a[1]||(a[1]=t("via:",-1)),n(e,{href:"http://news.softpedia.com/news/Red-Hat-and-Intel-Working-Closely-to-Bring-Wayland-as-Default-for-Fedora-21-383119.shtml"},{default:l(()=>[...a[0]||(a[0]=[t("http://news.softpedia.com/news/Red-Hat-and-Intel-Working-Closely-to-Bring-Wayland-as-Default-for-Fedora-21-383119.shtml",-1)])]),_:1})]),o("p",null,[a[4]||(a[4]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[2]||(a[2]=[t("LCTT",-1)])]),_:1}),a[5]||(a[5]=t(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/portal.php"},{default:l(()=>[...a[3]||(a[3]=[t("Linux中國",-1)])]),_:1}),a[6]||(a[6]=t(" 榮譽推出",-1))]),o("p",null,[a[9]||(a[9]=t("譯者：",-1)),n(e,{href:"http://linux.cn/space/14801"},{default:l(()=>[...a[7]||(a[7]=[t("Mr小眼兒",-1)])]),_:1}),a[10]||(a[10]=t(" 校對：",-1)),n(e,{href:"http://linux.cn/space/14763"},{default:l(()=>[...a[8]||(a[8]=[t("Caroline",-1)])]),_:1})])])}const F=d(f,[["render",u]]);export{_ as __pageData,F as default};
